import re

def parse_color(text):
    if not isinstance(text, str):
        raise ValueError()
    match = re.fullmatch(r'#([0-9a-fA-F]{3}|[0-9a-fA-F]{6})', text)
    if not match:
        raise ValueError()
    color_part = match.group(1)
    if len(color_part) == 3:
        expanded = ''.join(c * 2 for c in color_part)
    else:
        expanded = color_part
    r = int(expanded[0:2], 16)
    g = int(expanded[2:4], 16)
    b = int(expanded[4:6], 16)
    return (r, g, b)

def format_color(rgb):
    if not isinstance(rgb, (tuple, list)) or len(rgb) != 3:
        raise ValueError()
    for x in rgb:
        if not isinstance(x, int) or isinstance(x, bool):
            raise ValueError()
        if not (0 <= x <= 255):
            raise ValueError()
    r, g, b = rgb
    r_hex = "{:02x}".format(r)
    g_hex = "{:02x}".format(g)
    b_hex = "{:02x}".format(b)
    if (r_hex[0] == r_hex[1] and g_hex[0] == g_hex[1] and b_hex[0] == b_hex[1]):
        return '#' + r_hex[0] + g_hex[0] + b_hex[0]
    else:
        return '#' + r_hex + g_hex + b_hex

