    '8': '---..', '9': '----.'
}

def to_morse(text):
    if not isinstance(text, str):
        raise ValueError("Input must be a string")
    if text == "":
        return ""
    if text[0] == ' ' or text[-1] == ' ':
        raise ValueError("Invalid text spacing")
    if '  ' in text:
        raise ValueError("Invalid text spacing")
    words = text.split(' ')
    morse_words = []
    for word in words:
        for c in word:
            if not (c.isalpha() or c.isdigit()):
                raise ValueError("Invalid character")
        morse_chars = [morse_code_dict[c.upper()] for c in word]
        morse_words.append(' '.join(morse_chars))
    return ' / '.join(morse_words)

def from_morse(code):
    reverse_morse = {v: k for k, v in morse_code_dict.items()}
    if not isinstance(code, str):
        raise ValueError("Input must be a string")
    if code == "":
        return ""
    if code.startswith(' ') or code.endswith(' '):
        raise ValueError("Invalid code spacing")
    code_words = code.split(" / ")
    text_words = []
    for word in code_words:
        if word == "":
            raise ValueError("Invalid code word")
        if word.startswith(' ') or word.endswith(' '):
            raise ValueError("Invalid code word spacing")
        codes = word.split(' ')
        if '' in codes:
            raise ValueError("Invalid code word spacing")
        if ' '.join(codes) != word:
            raise ValueError("Invalid code word spacing")
        for c in codes:
            if c not in reverse_morse:
                raise ValueError("Invalid code")
        text_words.append(''.join([reverse_morse[c] for c in codes]))
    return ' '.join(text_words)

