import re

def snake_to_camel(name):
    if not isinstance(name, str):
        raise ValueError()
    if not re.fullmatch(r'^[a-z][a-z0-9]*(_[a-z][a-z0-9]*)*$', name):
        raise ValueError()
    parts = name.split('_')
    return parts[0] + ''.join(part.capitalize() for part in parts[1:])

def camel_to_snake(name):
    if not isinstance(name, str):
        raise ValueError()
    if not re.fullmatch(r'^[a-z][A-Za-z0-9]*$', name):
        raise ValueError()
    snake = []
    for char in name:
        if char.isupper():
            snake.append('_')
            snake.append(char.lower())
        else:
            snake.append(char)
    return ''.join(snake)

def cents_to_text(cents):
    if not isinstance(cents, int) or isinstance(cents, bool):
        raise ValueError("cents must be an integer, not a boolean or non-integer")
    sign = '-' if cents < 0 else ''
    total_cents = abs(cents)
    dollars = total_cents // 100
    cents_part = total_cents % 100

    def format_dollars(d):
        if d == 0:
            return '0'
        s = str(d)
        reversed_s = s[::-1]
        groups = []
        for i in range(0, len(reversed_s), 3):
            group = reversed_s[i:i+3]
            groups.append(group[::-1])
        groups.reverse()
        return ','.join(groups)

    dollars_str = format_dollars(dollars)
    cents_str = f"{cents_part:02d}"
    return f"{sign}{dollars_str}.{cents_str}"

