        raise ValueError("invalid decimal point")
    dollars_str, cents_str = parts
    if len(cents_str) != 2 or not cents_str.isdigit():
        raise ValueError("cents part must be exactly two digits")

    if not dollars_str:
        dollars = 0
    else:
        if dollars_str != "0" and len(dollars_str) > 1 and dollars_str[0] == '0':
            raise ValueError("invalid leading zero")
        groups = dollars_str.split(',')
        for group in groups:
            if not group.isdigit():
                raise ValueError("invalid group in dollars part")
        if len(groups) > 1:
            for group in groups[1:]:
                if len(group) != 3:
                    raise ValueError("invalid comma placement")
        if len(groups) == 1 and len(dollars_str) > 3:
