import re

def cents_to_text(cents):
    if type(cents) is not int:
        raise ValueError("Input must be an integer")
    if cents < 0:
        sign = '-'
        absolute_cents = -cents
    else:
        sign = ''
        absolute_cents = cents
    dollars = absolute_cents // 100
    cents_part = absolute_cents % 100
    dollars_str = "{:,}".format(dollars)
    cents_str = f"{cents_part:02d}"
    return f"{sign}{dollars_str}.{cents_str}"

def text_to_cents(text):
    if not isinstance(text, str):
        raise ValueError("Input must be a string")
    pattern = r'^(-?)(0|[1-9]\d*(?:,\d{3})*)\.(00|\d{2})$'
    match = re.fullmatch(pattern, text)
    if not match:
        raise ValueError("Invalid format")
    sign, dollars_part, cents_part = match.groups()
    dollars_num_str = dollars_part.replace(',', '')
    try:
        dollars_num = int(dollars_num_str)
    except ValueError:
        raise ValueError("Invalid number")
    formatted_dollars = "{:,}".format(dollars_num)
    if formatted_dollars != dollars_part:
        raise ValueError("Invalid comma placement")
    if dollars_num == 0 and int(cents_part) == 0 and sign == '-':
        raise ValueError("Negative zero is invalid")
    total_cents = dollars_num * 100 + int(cents_part)
    if sign == '-':
        total_cents = -total_cents
    return total_cents

def cidr_range(text):
    if text.count('/') != 1:
        raise ValueError
    ip_part, prefix_part = text.split('/')
    if not ip_part or not prefix_part:
        raise ValueError
    if ip_part.count('.') != 3:
        raise ValueError
    ip_parts = ip_part.split('.')
    if len(ip_parts) != 4:
        raise ValueError
    for part in ip_parts:
        if not part.isdigit():
            raise ValueError
        if len(part) > 1 and part[0] == '0':
            raise ValueError
        num = int(part)
        if not 0 <= num <= 255:
            raise ValueError
    if not prefix_part.isdigit():
        raise ValueError
    if len(prefix_part) > 1 and prefix_part[0] == '0':
        raise ValueError
    n = int(prefix_part)
    if not 0 <= n <= 32:
        raise ValueError
    a, b, c, d = [int(part) for part in ip_parts]
    ip_int = (a << 24) + (b << 16) + (c << 8) + d
    mask = ((1 << n) - 1) << (32 - n)
    first_address_int = ip_int & mask
    host_bits = 32 - n
    last_address_int = first_address_int | ((1 << host_bits) - 1)

    def int_to_ip(ip_int):
        a = (ip_int >> 24) & 0xFF
        b = (ip_int >> 16) & 0xFF
        c = (ip_int >> 8) & 0xFF
        d = ip_int & 0xFF
        return f"{a}.{b}.{c}.{d}"

    first = int_to_ip(first_address_int)
    last = int_to_ip(last_address_int)
    size = 1 << (32 - n)
    return (first, last, size)

