import re

def to_24h(text):
    if not isinstance(text, str):
        raise ValueError("Input must be a string")
    pattern = r'^([1-9]|1[0-2]):([0-5][0-9]) (AM|PM)$'
    match = re.fullmatch(pattern, text)
    if not match:
        raise ValueError("Invalid 12-hour time format")
    h12_str, min_str, period = match.groups()
    h12 = int(h12_str)
    mins = int(min_str)
    if period == 'AM':
        if h12 == 12:
            hh = 0
        else:
            hh = h12
    else:  # PM
        if h12 == 12:
            hh = 12
        else:
            hh = h12 + 12
    return f"{hh:02d}:{mins:02d}"

def to_12h(text):
    if not isinstance(text, str):
        raise ValueError("Input must be a string")
    pattern = r'^([0-1][0-9]|2[0-3]):([0-5][0-9])$'
    match = re.fullmatch(pattern, text)
    if not match:
        raise ValueError("Invalid 24-hour time format")
    hh24_str, min_str = match.groups()
    hh24 = int(hh24_str)
    mins = int(min_str)
    if hh24 == 0:
        h12 = 12
        period = 'AM'
    elif 1 <= hh24 < 12:
        h12 = hh24
        period = 'AM'
    elif hh24 == 12:
        h12 = 12
        period = 'PM'
    else:  # 13-23
        h12 = hh24 - 12
        period = 'PM'
    return f"{h12}:{mins:02d} {period}"

def luhn_valid(number):
    if not isinstance(number, str):
        raise ValueError
    if len(number) < 2:
        raise ValueError
    if not number.isdigit():
        raise ValueError
    reversed_num = number[::-1]
    total = 0
    for i, digit_char in enumerate(reversed_num):
        digit = int(digit_char)
        if i % 2 == 1:
            doubled = digit * 2
            if doubled > 9:
                doubled -= 9
            total += doubled
        else:
            total += digit
    return total % 10 == 0

def luhn_append(partial):
    if not isinstance(partial, str):
        raise ValueError
    if len(partial) < 1:
        raise ValueError
    if not partial.isdigit():
        raise ValueError
    reversed_partial = partial[::-1]
    sum_partial = 0
    for j, digit_char in enumerate(reversed_partial):
        digit = int(digit_char)
        if j % 2 == 0:
            doubled = digit * 2
            if doubled > 9:
                doubled -= 9
            sum_partial += doubled
        else:
            sum_partial += digit
    check_digit = (10 - (sum_partial % 10)) % 10
    return partial + str(check_digit)

