def parse_query(text):
    if not isinstance(text, str):
        raise ValueError("text must be a string")
    if text == '':
        return []
    parts = text.split('&')
    result = []
    for part in parts:
        if '=' not in part:
            raise ValueError("Part with no '='")
        split_parts = part.split('=', 1)
        key_part, value_part = split_parts
        if not key_part:
            raise ValueError("Empty key")
        try:
            decoded_key = decode(key_part)
            decoded_value = decode(value_part)
        except ValueError as e:
            raise ValueError(f"Invalid encoded part: {e}") from e
        result.append((decoded_key, decoded_value))
    return result

def decode(s):
    i = 0
    result = []
    while i < len(s):
        c = s[i]
        if c == '+':
            result.append(' ')
            i += 1
        elif c == '%':
            if i + 2 >= len(s):
                raise ValueError("Incomplete % escape")
            hex_part = s[i+1:i+3]
            try:
                code = int(hex_part, 16)
            except ValueError:
                raise ValueError("Invalid hex digits in % escape")
            if code > 0x7F:
                raise ValueError("Hex code above 0x7F")
            result.append(chr(code))
            i += 3
        else:
            if not (c.isalnum() or c in {'-', '.', '_', '~'}):
                raise ValueError("Invalid character in encoded string")
            result.append(c)
            i += 1
    return ''.join(result)

def build_query(pairs):
    if not isinstance(pairs, (list, tuple)):
        raise ValueError("pairs must be a list or tuple")
    for pair in pairs:
        if not isinstance(pair, tuple) or len(pair) != 2:
            raise ValueError("each pair must be a 2-tuple")
        key, value = pair
        if not isinstance(key, str) or not isinstance(value, str):
            raise ValueError("key and value must be strings")
        if not key:
            raise ValueError("empty key")
        for s in [key, value]:
            for c in s:
                if ord(c) >= 128:
                    raise ValueError("non-ASCII character")
    encoded_pairs = []
    for key, value in pairs:
        encoded_key = encode(key)
        encoded_value = encode(value)
        encoded_pairs.append(f"{encoded_key}={encoded_value}")
    return '&'.join(encoded_pairs)

def encode(s):
    encoded = []
