def persistence(n):
    if not (isinstance(n, int) and not isinstance(n, bool)) or n < 0:
        raise ValueError()
    if n < 10:
        return (0, 0)

    def additive_steps(num):
        count = 0
        while num >= 10:
            digits = list(map(int, str(num)))
            num = sum(digits)
            count += 1
        return count

    def multiplicative_steps(num):
        count = 0
        while num >= 10:
            digits = list(map(int, str(num)))
            product = 1
            for d in digits:
                product *= d
            num = product
            count += 1
        return count

    return (additive_steps(n), multiplicative_steps(n))


def digital_root(n):
    if not (isinstance(n, int) and not isinstance(n, bool)) or n < 0:
        raise ValueError()
    if n == 0:
        return 0
    remainder = n % 9
    return 9 if remainder == 0 else remainder

def phi(n):
    if type(n) is not int:
        raise ValueError()
    if n < 1 or n > 10**12:
        raise ValueError()
    if n == 1:
        return 1
    result = n
    if n % 2 == 0:
        result -= result // 2
        while n % 2 == 0:
            n = n // 2
    i = 3
    while i * i <= n:
        if n % i == 0:
            result -= result // i
            while n % i == 0:
                n = n // i
        i += 2
    if n > 1:
        result -= result // n
    return result

def totient_sum(limit):
    if type(limit) is not int:
        raise ValueError()
    if limit < 1 or limit > 100000:
        raise ValueError()
    t = list(range(limit + 1))
    for i in range(2, limit + 1):
        if t[i] == i:
            for j in range(i, limit + 1, i):
                t[j] -= t[j] // i
    return sum(t[1:])

