def generate_sieve(n):
    sieve = [True] * (n + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(n**0.5) + 1):
        if sieve[i]:
            for j in range(i*i, n+1, i):
                sieve[j] = False
    return sieve

def goldbach_pairs(n):
    validate_n(n)
    sieve_list = generate_sieve(n)
    count = 0
    max_p = n // 2
    for p in range(2, max_p + 1):
        if sieve_list[p] and sieve_list[n - p]:
            count += 1
    return count

def goldbach_smallest(n):
    validate_n(n)
    sieve_list = generate_sieve(n)
    max_p = n // 2
    for p in range(2, max_p + 1):
        if sieve_list[p] and sieve_list[n - p]:
            return (p, n - p)

def pascal_row_mod(n, m):
    if type(n) is not int or type(m) is not int:
        raise ValueError
    if not (0 <= n <= 2000):
        raise ValueError
    if not (2 <= m <= 10**9):
        raise ValueError
    row = [1]
    for k in range(1, n + 1):
        next_val = row[-1] * (n - k + 1) // k
        row.append(next_val)
    return [x % m for x in row]


def count_divisible(n, m):
    if type(n) is not int or type(m) is not int:
        raise ValueError
    if not (0 <= n <= 2000):
        raise ValueError
    if not (2 <= m <= 10**9):
        raise ValueError
    row_mod = pascal_row_mod(n, m)
    return row_mod.count(0)

import math

def primitive_triples(limit):
    _validate_limit(limit)
    triples = []
    m = 2
    while True:
        c_min = m * m + 1
        if c_min > limit:
            break
        for n in range(1, m):
            if math.gcd(m, n) != 1:
                continue
            if (m - n) % 2 == 0:
                continue
            c = m * m + n * n
            if c > limit:
                continue
            x = m * m - n * n
            y = 2 * m * n
            a, b = sorted([x, y])
            triples.append((a, b, c))
        m += 1
    triples.sort(key=lambda t: (t[2], t[0]))
    return triples

def count_triples(limit):
    _validate_limit(limit)
    return len(primitive_triples(limit))

def _validate_limit(limit):
    if type(limit) is not int or not (0 <= limit <= 100000):
        raise ValueError

def get_next(n):
    total = 0
    while n > 0:
        digit = n % 10
        total += digit ** 2
        n = n // 10
    return total

def is_happy(n):
    if type(n) is not int or n < 1:
        raise ValueError
    current = n
    while True:
        if current == 1:
            return True
        if current == 4:
            return False
        current = get_next(current)

def happy_count(limit):
    if type(limit) is not int or limit < 0 or limit > 100000:
        raise ValueError
    if limit == 0:
        return 0
    happy_cache = set()
    for i in range(1, 406):
        if is_happy(i):
            happy_cache.add(i)
    count = 0
    for n in range(1, limit + 1):
        first_step = get_next(n)
        if first_step in happy_cache:
            count += 1
    return count

import math

def egyptian(p, q):
    if not (isinstance(p, int) and isinstance(q, int)):
        raise ValueError()
    if isinstance(p, bool) or isinstance(q, bool):
        raise ValueError()
    if not (1 <= p < q <= 200):
        raise ValueError()
    denominators = []
    current_num = p
    current_den = q
    while current_num != 0:
        n = (current_den + current_num - 1) // current_num
        denominators.append(n)
        new_num = current_num * n - current_den
        new_den = current_den * n
        current_num, current_den = new_num, new_den
    return denominators

def unit_sum(denominators):
    if not isinstance(denominators, (list, tuple)):
        raise ValueError()
    for d in denominators:
        if not isinstance(d, int):
            raise ValueError()
        if isinstance(d, bool):
            raise ValueError()
        if d < 1:
            raise ValueError()
    num = 0
    den = 1
    for d in denominators:
        new_num = num * d + den
        new_den = den * d
        g = math.gcd(new_num, new_den)
        num = new_num // g
        den = new_den // g
    return (num, den)

from collections import deque

def two_color(n, edges):
    if type(n) is not int:
        raise ValueError
    if n < 0:
        raise ValueError
    if not (isinstance(edges, list) or isinstance(edges, tuple)):
        raise ValueError
    for edge in edges:
        if not isinstance(edge, (list, tuple)) or len(edge) != 2:
            raise ValueError
        a, b = edge
        if type(a) is not int or type(b) is not int:
            raise ValueError
        if a < 0 or a >= n or b < 0 or b >= n:
            raise ValueError
    for a, b in edges:
        if a == b:
            return None
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)
    color = [None] * n
    for start in range(n):
        if color[start] is None:
            color[start] = 0
            queue = deque()
            queue.append(start)
            while queue:
                node = queue.popleft()
                for neighbor in adj[node]:
                    if color[neighbor] is None:
                        color[neighbor] = 1 - color[node]
                        queue.append(neighbor)
                    elif color[neighbor] == color[node]:
                        return None
    return color

def closest_pair(points):
    if not isinstance(points, (list, tuple)):
        raise ValueError
    n = len(points)
    if n < 2 or n > 500:
        raise ValueError
    for i in range(n):
        point = points[i]
        if not (isinstance(point, (list, tuple)) and len(point) == 2):
            raise ValueError
        x, y = point
        if type(x) is not int or type(y) is not int:
            raise ValueError
        if not (-10**6 <= x <= 10**6) or not (-10**6 <= y <= 10**6):
            raise ValueError
    min_d2 = float('inf')
    min_i = 0
    min_j = 1
    for i in range(n):
        for j in range(i + 1, n):
            x1, y1 = points[i]
            x2, y2 = points[j]
            dx = x1 - x2
            dy = y1 - y2
            d2 = dx * dx + dy * dy
            if d2 < min_d2:
                min_d2 = d2
                min_i = i
                min_j = j
    return (min_d2, min_i, min_j)

