def euler_trail(n, edges):
    # Input validation
    if not isinstance(n, int):
        raise ValueError
    if n < 0:
        raise ValueError
    if not isinstance(edges, (list, tuple)):
        raise ValueError
    for edge in edges:
        if not (isinstance(edge, (list, tuple)) and len(edge) == 2):
            raise ValueError
        a, b = edge
        if type(a) is not int or type(b) is not int:
            raise ValueError
        if not (0 <= a < n and 0 <= b < n):
            raise ValueError

    if not edges:
        return []

    # Compute in_degree and out_degree
    in_degree = [0] * n
    out_degree = [0] * n
    for a, b in edges:
        out_degree[a] += 1
        in_degree[b] += 1

    # Check degree conditions
    start_vertices = []
    end_vertices = []
    for u in range(n):
        diff = out_degree[u] - in_degree[u]
        if diff == 1:
            start_vertices.append(u)
        elif diff == -1:
            end_vertices.append(u)
        elif diff != 0:
            return None

    if len(start_vertices) not in (0, 1) or len(end_vertices) not in (0, 1):
        return None
    if len(start_vertices) != len(end_vertices):
        return None

    # Determine starting vertex
    if len(start_vertices) == 1:
        start = start_vertices[0]
    else:
        start = None
        for u in range(n):
            if out_degree[u] > 0:
                if start is None or u < start:
                    start = u
        if start is None:
            return []

    # Build adjacency list with sorted deques
    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
    for u in range(n):
        adj[u].sort()
        adj[u] = deque(adj[u])

    # Hierholzer's algorithm
    stack = [start]
    result = []
    while stack:
        current = stack[-1]
        if adj[current]:
            next_v = adj[current].popleft()
            stack.append(next_v)
        else:
            stack.pop()
            result.append(current)

    trail = result[::-1]
    if len(trail) != len(edges) + 1:
        return None
    return trail

