            current = q.popleft()
            for neighbor in adj[current]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    distance[neighbor] = distance[current] + 1
                    q.append(neighbor)
                    if distance[neighbor] > max_dist:
                        max_dist = distance[neighbor]
                        farthest_node = neighbor
        return farthest_node, max_dist

    u, _ = bfs_max(0)
    v, D = bfs_max(u)

    def bfs_parents(start):
        parent = [-1] * n
        visited = [False] * n
        q = deque([start])
        visited[start] = True
        while q:
            current = q.popleft()
            for neighbor in adj[current]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    parent[neighbor] = current
                    q.append(neighbor)
        return parent

    parent = bfs_parents(u)

    path = []
    current = v
    while current != -1:
        path.append(current)
        current = parent[current]
    path = path[::-1]

    if D % 2 == 0:
        center_index = D // 2
        centers = [path[center_index]]
    else:
        center_index1 = D // 2
        center_index2 = center_index1 + 1
        centers = [path[center_index1], path[center_index2]]

    centers.sort()
    radius = (D + 1) // 2
    return (centers, radius)

def robot_walk(grid, commands):
    # Validate grid
    if not grid:
        raise ValueError
    rows = list(grid)
    row0 = rows[0]
    if not isinstance(row0, str):
        raise ValueError
    rows_count = len(rows)
    cols_count = len(row0)
    for row in rows:
        if len(row) != cols_count or not row:
            raise ValueError
    # Check characters and count 'S'
    s_count = 0
    for row in rows:
        for c in row:
            if c not in {'.', '#', 'S'}:
                raise ValueError
            if c == 'S':
                s_count += 1
    if s_count != 1:
        raise ValueError
    # Find start position
    start_row, start_col = None, None
    for r in range(rows_count):
        for c in range(len(rows[r])):
            if rows[r][c] == 'S':
                start_row, start_col = r, c
                break
        if start_row is not None:
            break
    # Validate commands
    for c in commands:
        if c not in {'L', 'R', 'F'}:
            raise ValueError
    # Initialize simulation
    current_row, current_col = start_row, start_col
    current_dir = 0  # North
    visited = {(current_row, current_col)}
    # Direction deltas: N, E, S, W
    dir_deltas = [(-1, 0), (0, 1), (1, 0), (0, -1)]
    # Process commands
    for cmd in commands:
        if cmd == 'L':
            current_dir = (current_dir - 1) % 4
        elif cmd == 'R':
            current_dir = (current_dir + 1) % 4
        elif cmd == 'F':
            dr, dc = dir_deltas[current_dir]
            new_row = current_row + dr
            new_col = current_col + dc
            # Check boundaries and wall
            if 0 <= new_row < rows_count and 0 <= new_col < cols_count:
                if rows[new_row][new_col] != '#':
                    current_row, current_col = new_row, new_col
                    visited.add((current_row, current_col))
    # Map direction to character
    dir_char = {0: 'N', 1: 'E', 2: 'S', 3: 'W'}
    return (current_row, current_col, dir_char[current_dir], len(visited))

