def elevator_stops(start, requests, direction):
    # Validate inputs
    if not isinstance(start, int):
        raise ValueError("Start must be an integer.")
    if not (0 <= start <= 1000):
        raise ValueError("Start must be between 0 and 1000.")
    if direction not in ("up", "down"):
        raise ValueError("Direction must be 'up' or 'down'.")
    if not isinstance(requests, (list, tuple)):
        raise ValueError("Requests must be a list or tuple.")
    for r in requests:
        if type(r) is not int:
            raise ValueError("Each request must be an integer.")
        if not (0 <= r <= 1000):
            raise ValueError("Each request must be between 0 and 1000.")

    unique_requests = set(requests)
    current_floor = start
    current_has_request = current_floor in unique_requests

    up_requests = [r for r in unique_requests if r > current_floor]
    down_requests = [r for r in unique_requests if r < current_floor]

    stops = []
    if current_has_request:
        stops.append(current_floor)

    if direction == "up":
        initial = sorted(up_requests)
        opposite = sorted(down_requests, reverse=True)
    else:  # direction == "down"
        initial = sorted(down_requests, reverse=True)
        opposite = sorted(up_requests)

    stops += initial
    stops += opposite

    # Calculate distance
    distance = 0
    current_pos = start
    for stop in stops:
        distance += abs(current_pos - stop)
        current_pos = stop

    return (stops, distance)

def elevator_stops(start, requests, direction):
    if type(start) is not int:
        raise ValueError
    if not (0 <= start <= 1000):
        raise ValueError
    if direction not in ("up", "down"):
        raise ValueError
    if not isinstance(requests, (list, tuple)):
        raise ValueError
    if len(requests) > 10000:
        raise ValueError
    for r in requests:
        if type(r) is not int:
            raise ValueError
        if not (0 <= r <= 1000):
            raise ValueError

    unique_requests = set(requests)
    stops = []
    current_floor = start

    if start in unique_requests:
        stops.append(start)
        unique_requests.remove(start)

    if direction == "up":
        group1 = sorted([f for f in unique_requests if f > start])
        group2 = sorted([f for f in unique_requests if f < start], reverse=True)
    else:
        group1 = sorted([f for f in unique_requests if f < start], reverse=True)
        group2 = sorted([f for f in unique_requests if f > start])

    stops += group1
    stops += group2

    total_distance = 0
    prev = start
    for floor in stops:
        total_distance += abs(floor - prev)
        prev = floor

    return (stops, total_distance)

def josephus(n, k):
    if type(n) is not int or type(k) is not int:
        raise ValueError
    if not (1 <= n <= 5000):
        raise ValueError
    if not (1 <= k <= 1000000):
        raise ValueError
    people = list(range(1, n + 1))
    result = []
    i = 0
    while people:
        i = (i + k - 1) % len(people)
        result.append(people.pop(i))
    return result

def josephus_survivor(n, k):
    if type(n) is not int or type(k) is not int:
        raise ValueError
    if not (1 <= n <= 1000000):
        raise ValueError
    if not (1 <= k <= 1000000):
        raise ValueError
    survivor = 0
    for m in range(2, n + 1):
        survivor = (survivor + k) % m
    return survivor + 1

def max_subarray(nums):
    if not isinstance(nums, (list, tuple)):
        raise ValueError
    if len(nums) == 0:
        raise ValueError
    if len(nums) > 100000:
        raise ValueError
    for v in nums:
        if type(v) is not int:
            raise ValueError
        if not (-10**9 <= v <= 10**9):
            raise ValueError

    current_prefix = 0
    min_prefix_value = 0
    min_prefix_index = 0
    best_sum = float('-inf')
    best_i = 0
    best_j = 0

    for j in range(len(nums)):
        current_num = nums[j]
        current_prefix += current_num
        current_candidate = current_prefix - min_prefix_value
        if current_candidate > best_sum:
            best_sum = current_candidate
            best_i = min_prefix_index
            best_j = j
        if current_prefix < min_prefix_value:
            min_prefix_value = current_prefix
            min_prefix_index = j + 1

    return (best_sum, best_i, best_j)

def stair_ways(n, steps, broken):
    mod = 10**9 + 7
    # Validate n
    if not isinstance(n, int):
        raise ValueError
    if n < 0 or n > 100000:
        raise ValueError
    # Validate steps
    if not isinstance(steps, (list, tuple, set)):
        raise ValueError
    steps_set = set(steps)
    if len(steps_set) == 0:
        raise ValueError
    if len(steps_set) < 1 or len(steps_set) > 10:
        raise ValueError
    for s in steps_set:
        if not isinstance(s, int) or isinstance(s, bool):
            raise ValueError
        if s < 1 or s > 100:
            raise ValueError
    # Validate broken
    if not isinstance(broken, (list, tuple, set)):
        raise ValueError
    if n == 0:
        if len(broken) != 0:
            raise ValueError
    else:
        for x in broken:
            if not isinstance(x, int) or isinstance(x, bool):
                raise ValueError
            if not (1 <= x <= n - 1):
                raise ValueError
    # Handle n == 0
    if n == 0:
        return 1
    # Prepare broken set
    broken_set = set(broken)
    valid_steps = list(steps_set)
    # Initialize DP array
    ways = [0] * (n + 1)
    ways[0] = 1
    for i in range(1, n + 1):
        if i in broken_set:
            ways[i] = 0
        else:
            total = 0
            for s in valid_steps:
                if s <= i:
                    total += ways[i - s]
            ways[i] = total % mod
    return ways[n]

