        raise ValueError
    for s in steps_list:
        if isinstance(s, bool):
            raise ValueError
        if not isinstance(s, int):
            raise ValueError
        if not (1 <= s <= 100):
            raise ValueError
    # Validate broken
    if not isinstance(broken, (list, tuple, set)):
        raise ValueError
