    for x in broken:
        if isinstance(x, bool):
            raise ValueError
        if not isinstance(x, int):
            raise ValueError
        if not (1 <= x <= n - 1):
            raise ValueError
        broken_set.add(x)
    # Handle n == 0
    if n == 0:
        return 1
    # DP calculation
    ways = [0] * (n + 1)
    ways[0] = 1
    for i in range(1, n + 1):
        if i in broken_set:
            ways[i] = 0
        else:
            total = 0
            for s in steps_list:
                prev = i - s
                if prev >= 0:
                    total += ways[prev]
