def lcs(a, b):
    if not isinstance(a, str) or not isinstance(b, str):
        raise ValueError
    if len(a) > 300 or len(b) > 300:
        raise ValueError
    m, n = len(a), len(b)

    # Precompute next occurrence tables
    next_a = [{} for _ in range(m + 1)]
    for i in range(m - 1, -1, -1):
        next_a[i] = next_a[i + 1].copy()
        next_a[i][a[i]] = i

    next_b = [{} for _ in range(n + 1)]
    for j in range(n - 1, -1, -1):
        next_b[j] = next_b[j + 1].copy()
        next_b[j][b[j]] = j

    # Build DP table
    L = [[0] * (n + 1) for _ in range(m + 1)]
    for i in reversed(range(m)):
        for j in reversed(range(n)):
            if a[i] == b[j]:
                L[i][j] = 1 + L[i + 1][j + 1]
            else:
                L[i][j] = max(L[i + 1][j], L[i][j + 1])

    # Reconstruct the lex smallest LCS
    def reconstruct(i, j):
        if i == m or j == n:
            return ''
        current_r = L[i][j]
        if current_r == 0:
            return ''

        set_a = set(next_a[i].keys())
        set_b = set(next_b[j].keys())
        common = set_a & set_b

        for c in sorted(common):
            x = next_a[i].get(c, None)
            if x is None:
                continue
            y = next_b[j].get(c, None)
            if y is None:
                continue
            if L[x + 1][y + 1] == current_r - 1:
                return c + reconstruct(x + 1, y + 1)
        return ''

    return reconstruct(0, 0)

def chain_order(dims):
    if not isinstance(dims, (list, tuple)):
        raise ValueError()
    n = len(dims)
    if n < 2 or n > 27:
        raise ValueError()
    for x in dims:
        if not isinstance(x, int) or isinstance(x, bool):
            raise ValueError()
        if x < 1 or x > 1000:
            raise ValueError()
    num_matrices = n - 1
    cost = [[0] * num_matrices for _ in range(num_matrices)]
    split = [[0] * num_matrices for _ in range(num_matrices)]
    for l in range(2, num_matrices + 1):
        for i in range(num_matrices - l + 1):
            j = i + l - 1
            cost[i][j] = float('inf')
            for s in range(i, j):
                current_cost = cost[i][s] + cost[s + 1][j] + dims[i] * dims[s + 1] * dims[j + 1]
                if current_cost < cost[i][j]:
                    cost[i][j] = current_cost
                    split[i][j] = s

    def build_order(i, j):
        if i == j:
            return chr(ord('A') + i)
        else:
            s = split[i][j]
            left = build_order(i, s)
            right = build_order(s + 1, j)
            return f"({left}{right})"

    return (cost[0][num_matrices - 1], build_order(0, num_matrices - 1))

def apply_ledger(events):
    if not isinstance(events, (list, tuple)):
        raise ValueError()
    balance = 0
    rejected = 0
    fees = 0
    for event in events:
        if not isinstance(event, (list, tuple)):
            raise ValueError()
        if len(event) == 0:
            raise ValueError()
        if not isinstance(event[0], str):
            raise ValueError()
        event_name = event[0]
        if event_name not in ('deposit', 'withdraw', 'month'):
            raise ValueError()
        if event_name == 'month':
            if len(event) != 1:
                raise ValueError()
        else:
            if len(event) != 2:
                raise ValueError()
            amount = event[1]
            if not (isinstance(amount, int) and not isinstance(amount, bool)):
                raise ValueError()
            if amount < 1:
                raise ValueError()
        if event_name == 'deposit':
            balance += event[1]
        elif event_name == 'withdraw':
            amount = event[1]
            if amount > balance:
                tentative_balance = balance - amount
                if tentative_balance >= -500:
                    balance = tentative_balance - 25
                    fees += 25
                else:
                    rejected += 1
            else:
                balance -= amount
        elif event_name == 'month':
            if balance < 0:
                charge = (-balance * 2) // 100
                balance -= charge
                fees += charge
    return (balance, rejected, fees)
